 path,_,frag=link.partition('#');target=f.parent/path if path else f
 if path and not target.exists():bad.append((link,'missing file'));continue
 if frag and target.suffix=='.html':
  q=p
  if path:q=P();q.feed(target.read_text())
  if frag not in q.ids:bad.append((link,'missing anchor'))
print('local link checks',len(p.links),'failures',bad)
for im in p.images:print('image',im.get('src'),'alt:',im.get('alt'))
for name in ['frequency-phase-delay-transfer.qmd']:
 a=Path('book')/name;print('manuscript SHA256',__import__('hashlib').sha256(a.read_bytes()).hexdigest())
