/usr/bin/bash -lc "python -B - <<'PY'
from pathlib import Path
from PIL import Image
import hashlib,re,xml.etree.ElementTree as ET,math
for p in sorted(Path('images').glob('*.png')):
 im=Image.open(p);print(p.name, im.size)
for n in ['frequency-transfer-orientation','frequency-exclusions','notch-observation','transfer-response']:
 a=Path('book/figures')/(n+'.svg');b=Path('rendered/figures')/(n+'.svg')
 print('source/rendered SVG identical',n,a.read_bytes()==b.read_bytes())
# Verify independently calculated plot coordinates against frozen SVG vertices.
ns={'s':'http://www.w3.org/2000/svg'}
for n in ['transfer-response','notch-observation']:
 root=ET.parse(Path('book/figures')/(n+'.svg')).getroot()
 curves=[]
 for e in root.findall('s:path',ns):
  pts=[(float(x),float(y)) for x,y in re.findall(r'[ML](-?[\\d.]+),(-?[\\d.]+)',e.attrib.get('d',''))]
  if len(pts)>200: curves.append((e.attrib.get('stroke'),pts))
 print(n,'curves',[(s,len(p)) for s,p in curves])
 for ci,(color,pts) in enumerate(curves):
  maxerr=0
  for x,y in pts:
   v=-100+(x-100)*200/780
   if n=='transfer-response':
    if ci<2:
     val=-360*v*1e3*10.025e-9-(2*math.atan(v/100)*180/math.pi if ci else 0)
     target=187+195-(val+100)*195/200
    else:
     val=.010025+(1e6/(math.pi*1e5*(1+(v/100)**2)) if ci==3 else 0)
     target=662+195-val*195/3.4
   else:
    mag=abs(2*math.cos(2*math.pi*(10e6-v)/1e8)-2*math.cos(.2*math.pi))
    val=max(-130,20*math.log10(max(mag,1e-12))) if ci==0 else 20*math.log10(max(mag,1e-12)+1e-6)
    target=197+195-(val+130)*195/40
   maxerr=max(maxerr,abs(y-target))
  print('curve',ci,'max SVG-coordinate discrepancy',maxerr)
PY"

